// #151 AC-3 -- the duplicate review page, rendered: the component the page uses is compiled and rendered to HTML
// from the review API's real answer (generated by the backend: scripts/gen-duplicate-review-fixture.cjs, kept in
// sync by its test), and every signal, its points, the total, the policy version, both versions and the
// paragraph differences shown must be the API's.
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { build } from "esbuild";

const root = fileURLToPath(new URL("../../", import.meta.url));
const review = JSON.parse(readFileSync(new URL("./fixtures/duplicate-review.json", import.meta.url), "utf8"));

/** The page's component, bundled with React and a router, as a function from a review to HTML. */
async function renderer() {
  const dir = mkdtempSync(join(tmpdir(), "dup-review-"));
  const outfile = join(dir, "render.mjs");
  await build({
    stdin: {
      contents: `
        import { createElement } from "react";
        import { renderToStaticMarkup } from "react-dom/server";
        import { MemoryRouter } from "react-router-dom";
        import { DuplicateReviewDetails } from "./src/features/duplicates/DuplicateReviewDetails.tsx";
        export const render = (review) => renderToStaticMarkup(
          createElement(MemoryRouter, null, createElement(DuplicateReviewDetails, { review, t: (s) => s, lang: "en", uploaderName: "Emma" })),
        );`,
      resolveDir: root,
      loader: "tsx",
    },
    bundle: true,
    format: "esm",
    platform: "node",
    jsx: "automatic",
    outfile,
    // React's CommonJS builds call require(); give the ES module bundle one.
    banner: { js: 'import { createRequire } from "node:module"; const require = createRequire(import.meta.url);' },
    define: { "process.env.NODE_ENV": '"production"' },
    logLevel: "silent",
  });
  const { render } = await import(pathToFileURL(outfile).href);
  return { render, done: () => rmSync(dir, { recursive: true, force: true }) };
}

const text = (html) => html.replace(/<[^>]+>/g, " ").replace(/&amp;/g, "&").replace(/&#x27;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, " ");

test("#151 AC-3: the review shows every signal with its points, the total and the policy version the API returned", async () => {
  const { render, done } = await renderer();
  try {
    const html = render(review);
    const shown = text(html);
    assert.ok(review.scoring.signals.length >= 5, "the sample has the signals to check");
    for (const signal of review.scoring.signals) {
      const row = html.match(new RegExp(`<tr data-signal="${signal.key}">(.*?)</tr>`))?.[1] ?? "";
      assert.ok(text(row).includes(signal.detail), `${signal.key}: detail`);
      assert.ok(text(row).includes(signal.points > 0 ? `+${signal.points}` : String(signal.points)), `${signal.key}: points`);
    }
    assert.equal(html.match(/<tr data-signal=/g)?.length, review.scoring.signals.length, "no signal left out or added");
    assert.match(html, new RegExp(`data-testid="score-total"[^>]*><strong>${review.scoring.total}</strong>`));
    assert.ok(shown.includes(`Scoring policy: ${review.scoring.policyVersion}`));
  } finally {
    done();
  }
});

test("#151 AC-3: both sides' files, sources, versions, the existing history and the paragraph differences are the API's", async () => {
  const { render, done } = await renderer();
  try {
    const shown = text(render(review));
    for (const value of [review.uploaded.fileName, review.existing.fileName, review.uploaded.email, review.existing.email]) assert.ok(shown.includes(value), value);
    assert.ok(shown.includes(`Would become v${review.uploaded.version} if confirmed`));
    assert.ok(shown.includes(`v${review.existing.version}`));
    assert.ok(shown.includes("Manual upload"), "the source as a readable label");
    for (const job of review.existing.employment) assert.ok(shown.includes(`${job.title} · ${job.company}`), job.title);
    for (const entry of review.existing.education) assert.ok(shown.includes(entry.school), entry.school);
    for (const line of review.differences.added) assert.match(render(review), new RegExp(`class="diff-added">${line}<`));
    for (const line of review.differences.removed) assert.match(render(review), new RegExp(`class="diff-removed">${line}<`));
    assert.ok(shown.includes(`${review.differences.unchanged} paragraphs are the same in both.`));
  } finally {
    done();
  }
});

test("#151 AC-3: a check stored before scoring shows its readable basis instead of a score table", async () => {
  const { render, done } = await renderer();
  try {
    const html = render({ ...review, scoring: null });
    assert.equal(html.match(/<tr data-signal=/g), null);
    for (const line of review.basis) assert.ok(text(html).includes(line), line);
  } finally {
    done();
  }
});
